-- Public Domain region-restricted publish (restrictions only), tag issue139_cl2_20261119.
-- 100 works / 417 chapters. Generated by scripts/public-domain/region-publish-sql.ts.
-- Each publication and each restriction row needs the owner's button approval
-- and an independent review (D030). Do not edit by hand; regenerate.
-- Writes series_region_restrictions only (no publication). Optional first
-- step: run this, wait at least 2 minutes (60 s app cache), then apply.sql.
-- Rows already equal to the reviewed list are kept; a differing row aborts.
begin;
set local lock_timeout = '5s';
set local statement_timeout = '60s';

create temporary table pd_region_targets (
  manifest_id text primary key,
  expected_title text not null,
  source_provider text not null,
  expected_episodes integer not null check (expected_episodes > 0),
  expected_warnings text[] not null,
  mode text not null check (mode in ('allow', 'block')),
  countries text[] not null,
  reason text not null
) on commit drop;


-- Resolve each manifest to exactly one series and lock it.
create temporary table pd_region_series on commit drop as
select t.manifest_id, s.id as series_id
from pd_region_targets t
join public.series s on s.effect_settings->'publicDomain'->>'manifestId' = t.manifest_id;

select s.id from public.series s
where s.effect_settings->'publicDomain'->>'manifestId' in ('aozora-000238', 'aozora-000239', 'aozora-000241', 'aozora-000737', 'aozora-000876', 'aozora-000879', 'aozora-000881', 'aozora-001817', 'aozora-001953', 'aozora-001954', 'aozora-001955', 'aozora-002159', 'aozora-002160', 'aozora-002162', 'aozora-004109', 'aozora-004803', 'aozora-004804', 'aozora-004805', 'aozora-024347', 'aozora-024357', 'aozora-042392', 'aozora-042393', 'aozora-042394', 'aozora-042617', 'aozora-042618', 'aozora-042621', 'aozora-042688', 'aozora-042689', 'aozora-043290', 'aozora-043620', 'aozora-043653', 'aozora-043656', 'aozora-043739', 'aozora-043763', 'aozora-043799', 'aozora-043804', 'aozora-043807', 'aozora-043847', 'aozora-044984', 'aozora-045169', 'aozora-045170', 'aozora-045171', 'aozora-045279', 'aozora-045280', 'aozora-045515', 'aozora-045516', 'aozora-045545', 'aozora-045648', 'aozora-045757', 'aozora-046070', 'aozora-046071', 'aozora-046074', 'aozora-046361', 'aozora-046387', 'aozora-046458', 'aozora-046470', 'aozora-046484', 'aozora-046488', 'aozora-046982', 'aozora-046983', 'aozora-046984', 'aozora-047001', 'aozora-047221', 'aozora-047224', 'aozora-047225', 'aozora-047417', 'aozora-047418', 'aozora-047513', 'aozora-047565', 'aozora-047592', 'aozora-047768', 'aozora-047856', 'aozora-047857', 'aozora-047942', 'aozora-047943', 'aozora-047945', 'aozora-048377', 'aozora-048379', 'aozora-048569', 'aozora-049255', 'aozora-049280', 'aozora-049287', 'aozora-049290', 'aozora-049296', 'aozora-049384', 'aozora-049701', 'aozora-049851', 'aozora-049868', 'aozora-049869', 'aozora-049870', 'aozora-050182', 'aozora-050183', 'aozora-050295', 'aozora-050296', 'aozora-050321', 'aozora-050322', 'aozora-050448', 'aozora-050533', 'aozora-050534', 'aozora-050924')
for update;

do $$ begin
  if (select count(*) from pd_region_series) <> 100
     or (select count(distinct manifest_id) from pd_region_series) <> 100
     or (select count(distinct series_id) from pd_region_series) <> 100 then
    raise exception 'PD_REGION_ISSUE139_CL2_20261119_SERIES_RESOLVE_MISMATCH';
  end if;
  if exists (
    select 1
    from pd_region_targets t
    join pd_region_series m using (manifest_id)
    join public.series s on s.id = m.series_id
    where s.publication_status <> 'private'
       or s.is_public is distinct from false
       or s.content_rating <> 'general'
       or s.title <> t.expected_title
       or not (s.content_warnings @> t.expected_warnings and s.content_warnings <@ t.expected_warnings)
       or s.effect_settings->'publicDomain'->>'rightsChecked' is distinct from 'true'
       or s.effect_settings->'publicDomain'->>'sourceProvider' is distinct from t.source_provider
  ) then raise exception 'PD_REGION_ISSUE139_CL2_20261119_SERIES_STATE_DRIFT'; end if;
  if (select count(distinct s.author_id) from pd_region_series m
      join public.series s on s.id = m.series_id) <> 1 then
    raise exception 'PD_REGION_ISSUE139_CL2_20261119_AUTHOR_DRIFT';
  end if;
  -- An existing row must already be exactly the reviewed list.
  if exists (
    select 1 from pd_region_targets t
    join pd_region_series m using (manifest_id)
    join public.series_region_restrictions r on r.series_id = m.series_id
    where not (
      (t.mode = 'allow' and r.blocked_countries is null
        and r.allowed_countries @> t.countries and r.allowed_countries <@ t.countries)
   or (t.mode = 'block' and r.allowed_countries is null
        and r.blocked_countries @> t.countries and r.blocked_countries <@ t.countries)
    )
  ) then raise exception 'PD_REGION_ISSUE139_CL2_20261119_EXISTING_RESTRICTION_DIFFERS'; end if;
end $$;

select m.series_id,
       case when t.mode = 'block' then t.countries end,
       case when t.mode = 'allow' then t.countries end,
       t.reason
from pd_region_targets t
join pd_region_series m using (manifest_id)
where not exists (
  select 1 from public.series_region_restrictions r where r.series_id = m.series_id
);

do $$ begin
  if (select count(*) from pd_region_targets t
      join pd_region_series m using (manifest_id)
      join public.series_region_restrictions r on r.series_id = m.series_id
      where (
      (t.mode = 'allow' and r.blocked_countries is null
        and r.allowed_countries @> t.countries and r.allowed_countries <@ t.countries)
   or (t.mode = 'block' and r.allowed_countries is null
        and r.blocked_countries @> t.countries and r.blocked_countries <@ t.countries)
    )) <> 100 then
    raise exception 'PD_REGION_ISSUE139_CL2_20261119_RESTRICTION_ROWCOUNT';
  end if;
end $$;
commit;
